import React from "react";

const ContactInfo = () => {
  return (
    <div className="d-flex gap-5 mb-4">
      <h4 className="contact-text fs-5">
        Mobile Number <br />
        <span className="fs-6">+135 773 321 4442</span>
      </h4>
      <h4 className="contact-text fs-5">
        Email Address <br />
        <span className="fs-6">demo@demo.com</span>
      </h4>
    </div>
  );
};

export default ContactInfo;
